from pathlib import Path

# r34: preserve native Smart-rule CharSequence styling and bound zero-pool
# Track Mix source lists at the already accepted MusicService.w1 boundary.

# --- PlaylistBridgeController: preserve native spans/style; replace only prefix.
p = Path("app/src/main/java/io/github/alagga/gonesmart/PlaylistBridgeController.kt")
t = p.read_text()
old = '''        collect(root)\n        if (exact.size != 1) return false\n        exact.single().text = replacement\n        return true\n'''
new = '''        collect(root)\n        if (exact.size != 1) return false\n        val target = exact.single()\n        val originalText = target.text ?: return false\n        if (originalText.toString() != expected) return false\n        val prefixEnd = playlist.length\n        if (prefixEnd <= 0 || prefixEnd > originalText.length) return false\n        // Keep GMMP's native CharSequence spans. Replacing the whole value\n        // with a plain String drops row-specific size/alignment styling.\n        val styled = android.text.SpannableStringBuilder(originalText)\n        styled.replace(0, prefixEnd, smartPlaylist)\n        target.text = styled\n        return true\n'''
if old not in t:
    raise SystemExit("PlaylistBridge label anchor missing")
t = t.replace(old, new, 1)
p.write_text(t)

# --- Pure source-window policy.
p = Path("app/src/main/java/io/github/alagga/gonesmart/TrackMixNativePlayWindowPolicy.kt")
p.write_text('''package io.github.alagga.gonesmart\n\n/**\n * Plans a bounded native MusicService playback source before GMMP materializes\n * queue rows. The target must occur exactly once; ambiguity always fails closed.\n */\ninternal object TrackMixNativePlayWindowPolicy {\n    data class Plan(\n        val startIndex: Int,\n        val endExclusive: Int\n    )\n\n    fun plan(\n        trackIds: List<Long>,\n        targetTrackId: Long,\n        initialSize: Int\n    ): Plan? {\n        if (trackIds.isEmpty() || initialSize <= 0 || targetTrackId <= 0L) return null\n        val matches = trackIds.indices.filter { trackIds[it] == targetTrackId }\n        if (matches.size != 1) return null\n        val start = matches.single()\n        return Plan(\n            startIndex = start,\n            endExclusive = minOf(trackIds.size, start + initialSize)\n        )\n    }\n}\n''')

# --- TrackMixController: request-scoped zero-pool source window.
p = Path("app/src/main/java/io/github/alagga/gonesmart/TrackMixController.kt")
t = p.read_text()
anchor = '''        @Volatile var prePlayPrepared: TrackMixPreparedInitialPool = TrackMixPreparedInitialPool.EMPTY\n        @Volatile var bootstrapAppliedTrackIds: List<Long> = emptyList()\n        @Volatile var bootstrapRefillObserved = false\n'''
replacement = '''        @Volatile var prePlayPrepared: TrackMixPreparedInitialPool = TrackMixPreparedInitialPool.EMPTY\n        @Volatile var prePlayInitialSize = 0\n        @Volatile var nativePlaybackWindowApplied = false\n        @Volatile var bootstrapAppliedTrackIds: List<Long> = emptyList()\n        @Volatile var bootstrapRefillObserved = false\n'''
if anchor not in t:
    raise SystemExit("TrackMix Pending anchor missing")
t = t.replace(anchor, replacement, 1)

anchor = '''                val initial = settings.read().initialQueueSize.coerceAtLeast(1)\n                val requiredUpcoming = (initial - 1).coerceAtLeast(0)\n                request.stage = "PREPLAY_PREPARE"\n'''
replacement = '''                val initial = settings.read().initialQueueSize.coerceAtLeast(1)\n                request.prePlayInitialSize = initial\n                val requiredUpcoming = (initial - 1).coerceAtLeast(0)\n                request.stage = "PREPLAY_PREPARE"\n'''
if anchor not in t:
    raise SystemExit("TrackMix initial size anchor missing")
t = t.replace(anchor, replacement, 1)

anchor = '''    fun onNativePlaybackMethodFinished(action: Int?) {\n        if (action == 0) onNativePlaybackQueueUpdated("MusicService.w1")\n    }\n\n'''
method = '''    /**\n     * r34: if provider recommendations are genuinely empty, bound a native\n     * Playlist/Smart-Playlist Play source before queue materialization. This\n     * prevents GMMP from replacing a short-lived selected queue_id with an\n     * entire source list while still leaving GMMP in charge of current+1 and\n     * AudioSource preparation. Prepared Smart-DJ bootstrap requests keep the\n     * proven r33 path unchanged.\n     */\n    fun windowNativePlaybackForTrackMix(\n        action: Int?,\n        tracks: List<*>\n    ): List<Any>? {\n        val request = pending ?: return null\n        if (action != 0 || request.stage != "WAIT_PLAY") return null\n        if (request.nativePlaybackWindowApplied) return null\n        if (request.prePlayPrepared.trackIds.isNotEmpty()) return null\n        val target = request.prePlayTarget ?: return null\n        val initial = request.prePlayInitialSize.coerceAtLeast(1)\n        if (tracks.size <= initial || tracks.isEmpty()) return null\n\n        val first = tracks.firstOrNull() ?: return null\n        val nativeClass = first.javaClass\n        val source = ArrayList<Any>(tracks.size)\n        val ids = ArrayList<Long>(tracks.size)\n        for (candidate in tracks) {\n            val track = candidate ?: run {\n                Log.w(TAG, "MIX NATIVE PLAY WINDOW | skipped=null-row")\n                return null\n            }\n            if (!nativeClass.isInstance(track)) {\n                Log.w(TAG, "MIX NATIVE PLAY WINDOW | skipped=mixed-model")\n                return null\n            }\n            val id = nativePlaybackTrackId(track) ?: run {\n                Log.w(\n                    TAG,\n                    "MIX NATIVE PLAY WINDOW | skipped=id-unresolved | model=" +\n                        nativeClass.name\n                )\n                return null\n            }\n            source += track\n            ids += id\n        }\n\n        val plan = TrackMixNativePlayWindowPolicy.plan(\n            trackIds = ids,\n            targetTrackId = target.id,\n            initialSize = initial\n        )\n        if (plan == null) {\n            Log.w(\n                TAG,\n                "MIX NATIVE PLAY WINDOW | skipped=target-ambiguous-or-missing" +\n                    " | original=${tracks.size} | target=${target.id}"\n            )\n            return null\n        }\n\n        val bounded = ArrayList(\n            source.subList(plan.startIndex, plan.endExclusive)\n        )\n        if (bounded.isEmpty()) return null\n        request.nativePlaybackWindowApplied = true\n        Log.i(\n            TAG,\n            "MIX NATIVE PLAY WINDOW | original=${tracks.size}" +\n                " | targetIndex=${plan.startIndex}" +\n                " | forwarded=${bounded.size}" +\n                " | initial=$initial | target=${target.id} | prepared=0"\n        )\n        return bounded\n    }\n\n    private fun nativePlaybackTrackId(track: Any): Long? = runCatching {\n        val getter = track.javaClass.methods.filter {\n            it.name == "getId" && it.parameterCount == 0\n        }.singleOrNull() ?: return@runCatching null\n        (getter.invoke(track) as? Number)?.toLong()\n    }.getOrNull()\n\n'''
if anchor not in t:
    raise SystemExit("TrackMix playback method anchor missing")
t = t.replace(anchor, anchor + method, 1)
p.write_text(t)

# --- GoneSmartModule: compose Track Mix source window with Queue Flip at the
# same accepted MusicService.w1 boundary. Prepared-pool requests return null
# from Track Mix and therefore retain the exact r33 path.
p = Path("app/src/main/java/io/github/alagga/gonesmart/GoneSmartModule.kt")
t = p.read_text()
t = t.replace('''        private const val COMPAT_PROBE_REVISION =\n            "gmmp421-r33"''', '''        private const val COMPAT_PROBE_REVISION =\n            "gmmp421-r34"''', 1)
old = '''            hook(playListMethod).intercept { chain ->\n                val action = chain.getArg(actionIndex) as? Int\n                val originalList = chain.getArg(listIndex) as? List<*>\n                val reversed = queueFlipController\n                    .consumeReversePlaylistForNativePlay(\n                        action,\n                        originalList\n                    )\n                if (reversed == null) {\n                    val result = chain.proceed()\n                    trackMixController.onNativePlaybackMethodFinished(action)\n                    result\n                } else {\n                    val args = Array<Any?>(playListMethod.parameterCount) {\n                        chain.getArg(it)\n                    }\n                    args[listIndex] = reversed.tracks\n                    Log.i(\n                        "GoneSmartFlip",\n                        "FLIP SERVICE | method=" + playListMethod.name +\n                            " | action=" + action +\n                            " | originalCount=" + originalList?.size +\n                            " | reversedCount=" + reversed.tracks.size\n                    )\n                    val result = playListMethod.invoke(\n                        chain.getThisObject(),\n                        *args\n                    )\n                    queueFlipController.verifyNativePlaylistPlayback(\n                        reversed.tracks,\n                        reversed.sourceKind\n                    )\n                    result\n                }\n            }\n'''
new = '''            hook(playListMethod).intercept { chain ->\n                val action = chain.getArg(actionIndex) as? Int\n                val originalList = chain.getArg(listIndex) as? List<*>\n                val trackMixWindow = originalList?.let { source ->\n                    trackMixController.windowNativePlaybackForTrackMix(\n                        action,\n                        source\n                    )\n                }\n                val effectiveList = trackMixWindow ?: originalList\n                val reversed = queueFlipController\n                    .consumeReversePlaylistForNativePlay(\n                        action,\n                        effectiveList\n                    )\n                val replacementList: List<*>? =\n                    reversed?.tracks ?: trackMixWindow\n                if (replacementList == null) {\n                    val result = chain.proceed()\n                    trackMixController.onNativePlaybackMethodFinished(action)\n                    result\n                } else {\n                    val args = Array<Any?>(playListMethod.parameterCount) {\n                        chain.getArg(it)\n                    }\n                    args[listIndex] = replacementList\n                    if (reversed != null) {\n                        Log.i(\n                            "GoneSmartFlip",\n                            "FLIP SERVICE | method=" + playListMethod.name +\n                                " | action=" + action +\n                                " | originalCount=" + originalList?.size +\n                                " | reversedCount=" + reversed.tracks.size\n                        )\n                    }\n                    val result = playListMethod.invoke(\n                        chain.getThisObject(),\n                        *args\n                    )\n                    if (reversed != null) {\n                        queueFlipController.verifyNativePlaylistPlayback(\n                            reversed.tracks,\n                            reversed.sourceKind\n                        )\n                    }\n                    trackMixController.onNativePlaybackMethodFinished(action)\n                    result\n                }\n            }\n'''
if old not in t:
    raise SystemExit("MusicService.w1 hook anchor missing")
t = t.replace(old, new, 1)
p.write_text(t)

# --- Unit tests for fail-closed source window planning.
p = Path("app/src/test/java/io/github/alagga/gonesmart/TrackMixNativePlayWindowPolicyTest.kt")
p.write_text('''package io.github.alagga.gonesmart\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertNull\nimport org.junit.Test\n\nclass TrackMixNativePlayWindowPolicyTest {\n    @Test\n    fun `unique target keeps target plus initial-size suffix window`() {\n        val plan = TrackMixNativePlayWindowPolicy.plan(\n            trackIds = listOf(10L, 20L, 30L, 40L, 50L, 60L, 70L),\n            targetTrackId = 30L,\n            initialSize = 5\n        )\n        assertEquals(2, plan?.startIndex)\n        assertEquals(7, plan?.endExclusive)\n    }\n\n    @Test\n    fun `target near end keeps only available native followers`() {\n        val plan = TrackMixNativePlayWindowPolicy.plan(\n            trackIds = listOf(10L, 20L, 30L, 40L),\n            targetTrackId = 30L,\n            initialSize = 5\n        )\n        assertEquals(2, plan?.startIndex)\n        assertEquals(4, plan?.endExclusive)\n    }\n\n    @Test\n    fun `duplicate target fails closed`() {\n        assertNull(\n            TrackMixNativePlayWindowPolicy.plan(\n                trackIds = listOf(10L, 20L, 20L, 30L),\n                targetTrackId = 20L,\n                initialSize = 5\n            )\n        )\n    }\n\n    @Test\n    fun `missing target fails closed`() {\n        assertNull(\n            TrackMixNativePlayWindowPolicy.plan(\n                trackIds = listOf(10L, 20L, 30L),\n                targetTrackId = 99L,\n                initialSize = 5\n            )\n        )\n    }\n\n    @Test\n    fun `invalid initial size fails closed`() {\n        assertNull(\n            TrackMixNativePlayWindowPolicy.plan(\n                trackIds = listOf(10L),\n                targetTrackId = 10L,\n                initialSize = 0\n            )\n        )\n    }\n}\n''')

# --- Durable rules/docs.
p = Path("AGENTS.md")
t = p.read_text()
t += '''\n\n### GMMP 4.2.1 r34 native label parity + zero-pool Track Mix source window\n- Smart-rule relabeling at `smartRuleListRecyclerView` must preserve GMMP's original `CharSequence` spans. Replace only the proven `Playlist` prefix inside a copied `SpannableStringBuilder`; never replace the whole styled label with a plain `String`, and never mutate TextView gravity, text size, typeface or layout parameters.\n- r33 device evidence proves a Smart-Playlist Play may start the selected audio on a short-lived queue entry and then delete/recreate that `queue_id` while materializing the full Smart Playlist. A disappearing selected `queue_id` is therefore not proof that playback failed.\n- For GMMP 4.2.1 Track Mix requests with a genuinely empty pre-Play GoneSmart recommendation pool, the accepted `MusicService.w1(action=0)` source-list boundary may be bounded *before queue materialization* to the uniquely pre-resolved selected track plus at most `Initial Size - 1` following native source rows. Apply this only while the exact request is `WAIT_PLAY`, only when the native source is larger than Initial Size, and only when native `getId()` maps the target exactly once. Missing/duplicate target or unsupported row shape leaves the native source untouched (fail closed).\n- A request with any prepared GoneSmart Track IDs must not use the r34 source window; it retains the device-accepted r33 bootstrap/refill path. The r34 source window is pre-materialization source shaping, not a post-materialization queue Track-ID retarget. `CLEAR_QUEUE`, post-retarget of `current+1`, and the retired same-position playback refresh remain forbidden.\n'''
p.write_text(t)

for doc in ["docs/GMMP_COMPATIBILITY_PLAYBOOK.md", "docs/GMMP_421_COMPLETION.md"]:
    p = Path(doc)
    t = p.read_text()
    t += '''\n\n## r34 focused repair\n- Preserve the native styled Smart-rule `CharSequence`; relabel only its proven `Playlist` prefix. No TextView geometry/typography mutation is allowed.\n- If Track Mix has zero prepared GoneSmart recommendations and GMMP is about to materialize a larger Playlist/Smart-Playlist through the accepted `MusicService.w1(action=0)` boundary, bound that native source pre-materialization to the unique selected target plus the available Initial-Size suffix. This prevents the selected temporary queue entry from being discarded by the full source rebuild while preserving GMMP ownership of current+1/AudioSource preparation.\n- Prepared-recommendation Track Mix (including the r33 Levels acceptance path) is unchanged. Missing/duplicate targets fail closed. `CLEAR_QUEUE`, post-materialization Track-ID retarget and same-position refresh stay retired.\n'''
    p.write_text(t)

