# Guards.
for path, required in {
    "app/src/main/java/io/github/alagga/gonesmart/GoneSmartModule.kt": ["gmmp421-r34", "windowNativePlaybackForTrackMix"],
    "app/src/main/java/io/github/alagga/gonesmart/TrackMixController.kt": ["MIX NATIVE PLAY WINDOW", "prePlayInitialSize"],
    "app/src/main/java/io/github/alagga/gonesmart/PlaylistBridgeController.kt": ["SpannableStringBuilder(originalText)"],
}.items():
    text = Path(path).read_text()
    for marker in required:
        if marker not in text:
            raise SystemExit(f"guard missing {path}: {marker}")

print("r34 patch applied")
